    street: { bpm: 128, root: 60, bass: [0, null, 0, null, 7, null, 5, null, 0, null, 0, null, 3, null, 5, 7], lead: [12, null, 16, null, 19, 16, null, 14, 12, null, 9, null, 12, 14, null, null], hat: true },
