function topAt(x) { var y = groundY(x); if (G && G.solids) G.solids.forEach(function (o) { if (!o.gone && o.k !== "edge" && Math.abs(x - o.x) < o.w / 2 - 6 && o.top < y) y = o.top; }); return y; }

/* ---------- STAGE 2: THE PARK (ported from the canvas Park slice: same positions) ---------- */
function buildPark(L) {
  var F = L.F, line = L.line, arc = L.arc, crate = L.crate, gift = L.gift, wall = L.wall, bush = L.bush, bunny = L.bunny;
  [["banner", 1000], ["scrap0", 2000], ["scrap1", 2120], ["scrap0", 4300], ["banner", 5560], ["scrap1", 7700], ["scrap0", 7850]].forEach(function (s) { L.story.push({ k: s[0], x: s[1] }); });
  /* 1. a gift box, the first present bush, a tiny bunny in a hat (it faints at any attack) */
  line(300, 6, 40); gift(600); bush(820, "present"); F(820, groundY(820) - 120);
  bunny(1030, "tiny"); crate(1180, 1); arc(1060, 1320, 100, 5);
  line(1450, 15, 40);                                   /* down the first hill */
  bunny(1750, "fast"); bush(2060, "flowers");
  /* 2. the pond, a grumpy big bunny, a hedge */
  arc(2160, 2600, 120, 10); bunny(2620, "big");
  wall(2860, 140); arc(2720, 3000, 110, 6);
  /* 3. a gift box, then the bunny crew in the fight zone */
  gift(3130); line(3990, 5, 40);
  bush(4080, "present"); crate(4260, 1); crate(4322, 2); F(4260, groundY(4260) - 98); F(4322, groundY(4322) - 156); arc(4360, 4620, 100, 5, groundY(4322) - 116 + 40);
  /* 4. the second hill, a fast bunny, a bush with a bunny in it, the second pond */
  bunny(4720, "fast"); bush(4880, "bunny"); line(4560, 10, 40);
  arc(5010, 5470, 130, 10);
  bush(5520, "present"); bunny(5620, "big"); bush(5720, "present");
  /* 5. THE BOARD (Tony Hawk in the park): pick it up and ride. Three bumps to ride over (jump off the top of each for
     the dahlias above it), the big slide down, the kicker, a kickflip, and the board flies on and bonks Fluffini */
  line(5800, 2, 40);
  L.trailStart(); for (var b1 = 0; b1 < 6; b1++) F(6000 + b1 * 46, groundY(6000 + b1 * 46) - 70 - Math.sin(b1 / 5 * Math.PI) * 90); L.trailEnd();
  arc(6380, 6720, 210, 7, groundY(6550) + 40);
  L.trailStart(); for (var b2 = 0; b2 < 8; b2++) { var bx = 6800 + b2 * 62; F(bx, groundY(bx) - 60 - Math.sin(b2 / 7 * Math.PI) * 160); } L.trailEnd();
  for (var s2 = 0; s2 < 5; s2++) { var sx = 7090 + s2 * 50; F(sx, groundY(sx) - 50); }
  arc(PARK.kicker + 40, PARK.kicker + 420, 220, 7, groundY(PARK.kicker) - 20);   /* the kickflip flies through these */
  gift(PARK.fluff - 560);                               /* a gift box where she lands, so she can meet Fluffini bloomed */
}

/* ---------- STAGE 3: PARTY ROAD. The street at dusk, Snuffles' bats in a fight zone, the gate onto the rooftops,
   a climb over seven roofs (two need the double jump), THE HIGH FALL into the party's bouncy castle, then Snuffles
   at the house. Every alley between houses has crates to climb back up: a fall is never a dead end. ---------- */
var ROOFS_L = [[2560, 500, 150], [3200, 400, 230], [3780, 400, 330], [4300, 800, 330], [5420, 400, 400], [5980, 400, 340], [6505, 375, 380]], ROOFS = ROOFS_L;
function buildRoad(L) {
  var F = L.F, line = L.line, arc = L.arc, crate = L.crate, gift = L.gift, bat = L.bat, roof = L.roof;
  /* 1. the street at dusk: bunting, crates, two lookout bats */
  line(300, 6, 40); crate(700, 1); arc(620, 860, 110, 5);
  bat(980, "fly", 175); gift(1120);
  /* 2. the fight zone: Snuffles' bats come down from both sides */
  line(1980, 5, 40);
  /* 3. the gate onto the rooftops: crates up to the first roof */
  crate(ROAD.gate + 20, 1); crate(ROAD.gate + 82, 2); F(ROAD.gate + 20, groundY(0) - 58 - 40); F(ROAD.gate + 82, groundY(0) - 116 - 40);
  ROOFS.forEach(function (r, i) { roof(r[0], r[1], r[2], i); });
  var top = function (i) { return BASE - ROOFS[i][2]; };
  /* roof 1 and 2: run and jump */
  line(2600, 8, 40 + 150); arc(3040, 3230, 120, 5, top(0));
  bat(3400, "hang", 0);
  /* roof 3: up a level; a double jump reaches the high dahlias above it */
  L.trailStart(); for (var hk = 0; hk < 5; hk++) F(3880 + hk * 60, top(2) - 230 - Math.sin(hk / 4 * Math.PI) * 40); L.trailEnd();
  L.trailStart(); for (var k = 0; k < 6; k++) F(3620 + k * 34, top(1) - 60 - k * 46); L.trailEnd();
  /* roof 4: the long flat roof with a flag, lookouts */
  line(4320, 14, 40 + 330); bat(4700, "fly", 140); bat(5000, "hang", 0);
  /* roof 5: the wide gap, the second double jump */
  arc(5110, 5440, 190, 8, top(3));
  /* roof 6 and 7: down then up to the tower: the high fall starts at its edge */
  arc(5830, 6000, 100, 4, top(4)); bat(6200, "fly", 120); arc(6390, 6500, 120, 4, top(5)); line(6520, 6, 40 + 380);
  /* crates in every alley so a fall is never a dead end */
  /* each alley is a staircase of crates rising to the next roof, so falling in is never a dead end */
  [[3105, 1], [3168, 2], [3627, 1], [3688, 2], [3749, 3], [4210, 2], [4270, 3], [5210, 1], [5270, 2], [5330, 3], [5390, 4], [5890, 2], [5950, 3], [6411, 2], [6471, 4]].forEach(function (c) { for (var i = 0; i < c[1]; i++) L.obj({ k: "box", x: c[0], w: 60, h: 58, br: false, base: groundY(c[0]) - 58 * i }); });   /* sturdy boxes: they cannot be smashed */
  /* the garden after the fall: dahlias to the house */
  line(7300, 6, 40);
}

