  if (!scene.textures.exists(key)) { var t = TEXT_CACHE[key] || (TEXT_CACHE[key] = scene.make.text({ x: 0, y: 0, text: text, style: style, add: false })); scene.textures.addCanvas(key, t.canvas); }
