  if (this.hp === 3 && !this.halfSaid) { this.halfSaid = true; S.bigText("SNUFFLES IS CROSS!", "#ff5a5a", 1.2, true); var me = this; S.time.delayedCall(1300, function () { S.bubble(me, "Nobody ever invites ME!", 2.4); }); }   /* the big word first, then his line */
