    if (inFront) { var facing = (this.x > P.x) === (P.face === 1);
      if (P.block && facing) { if (!this.blocked) { this.blocked = true; S.float(P.x, P.y - 140, "BLOCKED!", "#3fd8c7", true); fx("block", 0.55, 0.8); } P.vx = this.face * 40; }
      else if (this.t > 0.2) { P.vx = this.face * 820; if (!this.hitP && !this.blocked && this.t < 0.4 && G.mercy < 2 && Math.abs(P.x - this.x) < (G.mercy >= 1 ? 150 : 190)) { this.hitP = true; hurtPlayer(this.x); P.vx = this.face * 820; }   /* quiet help: shorter reach after a lost try, only a push after two */ } }   /* the gust reaches her 0.2 s in: time to block */
