    if (liveL.length >= 2) { liveL.sort(function (a1, b1) { return (a1.born || 0) - (b1.born || 0); }); var old = liveL[0]; this.tweens.killTweensOf(old); old.busy = false; old.setVisible(false); }
    var cam = this.cameras.main, V = cam.worldView; x = clamp(x, V.x + 120, V.x + V.width - 120); y = clamp(y, V.y + 215, V.y + V.height - 60);
