/* ---------- THE OPENING (OVERNIGHT2, C), in the game itself, about 4 s: Matilda training at the dojo, Leo calls for
   help (Snuffles has taken over the party), Sensei says go, she runs out of the gate and is playing. A tap skips it. ---------- */
Object.assign(Stage.prototype, {
  intro: function () {
    var P = G.P; G.intro = true; G.introT = 0; G.introStep = 0; P.x = DOJO_START; P.y = BASE; P.face = 1; MUS.play("street");
    this.introSen = this.add.image(120, BASE, "sensei", "se0").setOrigin(0.5, 1).setScale(1 / 1.5, 1 / 1.5).setDepth(48);
    var me = this; this.skipFn = function () { if (G && G.intro && G.introT > 0.3) G.skipIntro = true; };
    window.addEventListener("pointerdown", this.skipFn, true); window.addEventListener("keydown", this.skipFn, true);
  },
  introUpdate: function (real) {
    var P = G.P, S = this, t = (G.introT += real), st = G.introStep, D = this.dummy;
    var hitD = function (m, line) { sStart(P, m); S.time.delayedCall(110, function () { if (D) { S.tweens.killTweensOf(D); D.angle = 0; S.tweens.add({ targets: D, angle: 9, duration: 90, yoyo: true, ease: "Quad.easeOut" }); } fx(m === "kick" ? "kick" : "punch0", 0.5); S.sparks(430, BASE - 100, 6); }); if (line) say("hiya", true); };
    if (G.skipIntro && st < 5) { G.introStep = st = 5; t = G.introT = Math.max(t, 3.6); if (this.hud) this.hud.leoCall(false); }
    if (st === 0 && t > 0.15) { G.introStep = 1; hitD("jab", true); }
    else if (st === 1 && t > 0.55) { G.introStep = 2; hitD("cross"); }
    else if (st === 2 && t > 1.0) { G.introStep = 3; if (this.hud) this.hud.leoCall(true); voice("l_help"); fx("chime", 0.35, 2.2); }
    else if (st === 3 && t > 3.0) { G.introStep = 4; P.face = -1; this.bubble({ x: 120, y: BASE + 30, k: "sensei" }, "Go! Get to the party!", 1.3); this.introSen.setFrame("se1"); MUS.voice(1.2); }
    else if (st === 4 && t > 3.6) G.introStep = st = 5;
    if (st === 5) { G.introStep = 6; if (this.hud) this.hud.leoCall(false); this.introSen.setFrame("se0"); P.face = 1; say("coming", true); G.autoRight = true; if (this.hud && this.hud.route) this.hud.route(true); }
    if (st >= 5 && (P.x > DOJO_W + 40 || IN.left || IN.right || IN.q.length && t > 4.2)) this.introEnd();
  },
  introEnd: function () { G.intro = false; G.autoRight = false; G.skipIntro = false; window.removeEventListener("pointerdown", this.skipFn, true); window.removeEventListener("keydown", this.skipFn, true); G.stats.introT = +G.introT.toFixed(1); }
});

