  toStage: function () { var S = this; window.skipOpening = null; RUN.fromOpening = true; wipeCover(function () { game.scene.stop("story"); stageArt("street", function () { game.scene.start("stage"); }); }); },
  /* ---------- the ending: the family runs out, Sensei bows to his black belt, the dahlia for Mummy, everyone goes in ---------- */
