    var mat = this.actor("matilda", HX + 380, -1, 1.15), sn = this.actor("snuffles", HX - 210, 1, 1.15), mum = this.actor("mummy", HX, 1), leo = this.actor("leo", HX, 1), sen = this.actor("sensei", HX + 540, -1);
