    this.at(0.8, function () { leo.vis = true; S.walkTo(leo, HX + 270, 900, function () { leo.face = 1; leo.pose = "cheer"; S.say(leo, "You were AMAZING!", 2.2); fx("chime", 0.4, 1.6); }); });
